          "signature": "neighborResponse struct { FormatVersion int `json:\"format_version\"` RepoRoot string `json:\"repo_root\"` Commit string `json:\"commit,omitempty\"` Tree string `json:\"tree,omitempty\"` Profile string `json:\"profile\"` Relation string `json:\"relation\"` // Direction echoes which half of the adjacency was asked for. Without it a // reader cannot tell an empty section from a section that was never queried. Direction string `json:\"direction\"` Query string `json:\"query\"` File string `json:\"file,omitempty\"` Line int `json:\"line,omitempty\"` IndexCacheHit bool `json:\"index_cache_hit\"` // IndexCacheDisabled records that this run had nowhere to store the index it // built, so the next relation query pays the same cost again. Relation verbs // index the WHOLE repository (search only parses its candidate files), which // makes that difference tens of seconds on a large repo — a cost the CLI // surface otherwise never states. IndexCacheDisabled bool `json:\"index_cache_disabled,omitempty\"` IndexLatencyMS int64 `json:\"index_latency_ms\"` QueryLatencyMS int64 `json:\"query_latency_ms\"` TotalLatencyMS int64 `json:\"total_latency_ms\"` Truncated bool `json:\"truncated\"` FocusMatchesTotal int `json:\"focus_matches_total\"` // FuzzyMatch reports that no EXACT match existed and these candidates came from the fuzzy ladder. // FuzzyMatchKind names the rung, so a consumer is never misled about what it asked for. FuzzyMatch bool `json:\"fuzzy_match,omitempty\"` FuzzyMatchKind string `json:\"fuzzy_match_kind,omitempty\"` // MatchBodies carries source for the first few matched definitions, so an ambiguous or fuzzy // answer removes the follow-up read instead of prescribing one. MatchBodies []symbolMatchBody `json:\"match_bodies,omitempty\"` FocusMatchesTruncated bool `json:\"focus_matches_truncated\"` DisambiguationRequired bool `json:\"disambiguation_required\"` Matches []neighborFocus `json:\"matches\"` Warnings []sem.ProviderWarning `json:\"warnings,omitempty\"` PartialFailures []sem.PartialFailure `json:\"partial_failures\"` Stats sem.ProviderStats `json:\"stats\"` Completeness sem.CompletenessReport `json:\"completeness\"` // CompletenessScope is the query-relative reading of the diagnostics above. // The full lists stay untouched; this says which of them can matter here. CompletenessScope completenessScope `json:\"completeness_scope\"` // endpointTruncated distinguishes a bounded neighbor list from the JSON-only // explicit path expansion. Agent output can express the full Cartesian path // family compactly, so path expansion alone is not a truncation for agents. endpointTruncated bool }"
