				continue
			}
			cmd.Env = append(cmd.Env, entry)
		}
	}
	cmd.WaitDelay = 2 * time.Second

	out, stderr := &limitedBuffer{limit: 1 << 20}, &limitedBuffer{limit: 64 << 10}
	cmd.Stdout = out
	cmd.Stderr = stderr
	err := cmd.Run()
