  default:
   // Redirects carry no activation of their own. An unknown canonical guide
   // must not silently lose a previously enabled product.
   if name == Path { return nil, fmt.Errorf("unrecognized repository agent guide heading in %s", name) }
  }
 }
 return active, nil
}
