  activationPrefix+`{"schema_version":1,"enabled":["unknown"]}`+activationSuffix,
  activationPrefix+`{"schema_version":1,"enabled":["graph","graph"]}`+activationSuffix,
  activationPrefix+`{"schema_version":1,"enabled":[]}`+activationSuffix,
